pub fn write_overlay(
    root: &Path,
    kernel_dir: &Path,
    opts: &InitOptions,
    contract_override: Option<Value>,
) -> Result<Vec<String>> {
    let tdir = kernel_dir.join("overlay-templates");
    let odir = root.join("governance").join("project");
    std::fs::create_dir_all(&odir)?;
    let mut written = vec![];
    for fname in crate::policy::OVERLAY_FILES.iter().map(|(f, _)| *f) {
        let dest = odir.join(fname);
        if dest.exists() && !opts.force {
            continue;
        }
        if fname == "REPOSITORY_CONTRACT.yaml" {
            if let Some(c) = &contract_override {
                write_yaml(&dest, c)?;
                written.push(fname.to_string());
                continue;
            }
        }
        let tpl = tdir.join(fname);
        if !tpl.exists() {
            continue;
        } // older kernels may not ship every template
        let mut text = read_text(&tpl)?;
        for (k, v) in [
            ("{{project_name}}", opts.project_name.as_str()),
            ("{{project_alias}}", opts.alias.as_str()),
            ("{{today}}", &today()),
            ("{{mode}}", opts.mode.as_str()),
        ] {
            text = text.replace(k, v);
        }
        write_text(&dest, &text)?;
        written.push(fname.to_string());
    }
    Ok(written)
}

/// Map a project's native layout into the repository contract instead of moving it (framework §8.1).
pub fn native_layout_rules(root: &Path) -> Vec<Value> {
    let mut rules = vec![];
    let Ok(rd) = std::fs::read_dir(root) else {
        return rules;
    };
    let mut dirs: Vec<String> = rd
        .filter_map(|e| e.ok())
        .filter(|e| e.path().is_dir())
        .map(|e| e.file_name().to_string_lossy().to_string())
        .collect();
    dirs.sort();
    for d in dirs {
        if d.starts_with('.')
            || crate::paths::ALWAYS_EXCLUDED_DIRS.contains(&d.as_str())
            || [
                "governance",
                "spec",
                "archive",
                "product",
                "docs",
                "fixtures",
                "release",
                "lessons",
                "change-proposals",
            ]
            .contains(&d.as_str())
        {
            continue;
        }
        // AR84-C1: this used to check only the FIRST 400 entries of `iter_repo_files`'s walkdir/file-name order
        // (`.take(400)`) -- a bound on how many entries the `.any()` below inspects, not on the walk itself
        // (`iter_repo_files` always collects the whole directory into memory first). A directory whose first 400
        // file names sort before any file with a recognised code extension (450 ordinary `.txt` decoys under
        // `src/aaa/`, added by the SAME ordinary edit the AR82-C2 threat model already assumes) therefore judged a
        // genuinely code-bearing directory to hold no code at all, silently dropping it from the reconstructed
        // floor. Scanning every collected entry removes the file-count/ordering sensitivity structurally, at the
        // cost of no additional directory walk (the walk already happened); `.any()` still short-circuits on the
        // first match, so an ordinary repository with code near the top of its directory listing pays nothing extra.
        let has_code = crate::paths::iter_repo_files(&root.join(&d), false)
            .iter()
            .any(|(_, rel)| {
                Path::new(rel)
                    .extension()
                    .map(|e| {
                        crate::capabilities::ecosystems::language_for_ext(&e.to_string_lossy())
                            .is_some()
                    })
                    .unwrap_or(false)
            });
        if !has_code {
            continue;
        }
        let is_test = matches!(
            d.as_str(),
            "tests" | "test" | "__tests__" | "spec_tests" | "e2e"
        );
        rules.push(json!({"pattern": format!("{d}/**"), "class": if is_test { "test" } else { "source" }, "owner_role": if is_test { "independent-test-designer" } else { "backend-engineer" }, "semantic_index": true, "lexical_index": true, "graph_index": true, "code_index": true, "namespace": "product"}));
    }
    rules
}

